module i2c_master (  
    input wire clk,  
    input wire start,  
    input wire [6:0] slave_addr,  
    input wire [7:0] data_in,  
    output reg sda,  
    output reg scl,  
    output reg done  
);  
    reg [2:0] state;  
    reg [3:0] bit_cnt;  
    reg [7:0] data_reg;  
    parameter IDLE = 3'b000, START = 3'b001, ADDR = 3'b010, WRITE = 3'b011, READ = 3'b100, STOP = 3'b101;  

    always @(posedge clk) begin  
        case (state)  
            IDLE: begin  
                if (start) begin  
                    state <= START;  
                    done <= 0;  
                end  
            end  
            START: begin  
                sda <= 0;  
                scl <= 0;  
                state <= ADDR;  
                data_reg <= {slave_addr, 1'b0};  
                bit_cnt <= 7;  
            end  
            ADDR: begin  
                sda <= data_reg[bit_cnt];  
                scl <= 1;  
                if (bit_cnt == 0) begin  
                    state <= WRITE;  
                    bit_cnt <= 7;  
                    data_reg <= data_in;  
                end else begin  
                    bit_cnt <= bit_cnt - 1;  
                end  
            end  
            WRITE: begin  
                sda <= data_reg[bit_cnt];  
                scl <= 1;  
                if (bit_cnt == 0) begin  
                    state <= STOP;  
                end else begin  
                    bit_cnt <= bit_cnt - 1;  
                end  
            end  
            STOP: begin  
                scl <= 1;  
                sda <= 1;  
                state <= IDLE;  
                done <= 1;  
            end  
        endcase  
    end  
endmodule

