module watchdog_timer (
    input wire clk,
    input wire reset_n,
    input wire signal_in,
    output reg reset_out
);
    parameter TIMEOUT = 10; // Timeout period in clock cycles
    reg [3:0] counter; // 4-bit counter for timeout

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            reset_out <= 0;
            counter <= 0;
        end else begin
            if (signal_in) begin
                // Reset the counter on signal_in toggle
                counter <= 0;
                reset_out <= 0;
            end else if (counter < TIMEOUT) begin
                // Increment counter if not timed out
                counter <= counter + 1;
                reset_out <= 0;
            end else begin
                // Set reset_out high if timeout occurs
                reset_out <= 1;
            end
        end
    end
endmodule

