module deserializer (  
    input wire clk,  
    input wire reset,  
    input wire serial_in,  
    output reg [15:0] parallel_out  
);  
    reg [3:0] bit_counter;  
    reg [15:0] shift_register;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            bit_counter <= 0;  
            shift_register <= 0;  
            parallel_out <= 0;  
        end else begin  
            shift_register <= {shift_register[14:0], serial_in};  
            bit_counter <= bit_counter + 1;  
            if (bit_counter == 15) begin  
                parallel_out <= shift_register;  
                bit_counter <= 0;  
            end  
        end  
    end  
endmodule

