module IIR_Filter (  
    input clk,  
    input reset,  
    input signed [15:0] x_in,  
    output reg signed [15:0] y_out  
);  
    reg signed [15:0] y_prev;  
    parameter signed [15:0] a1 = 16'h0C00; // Coefficient for the feedback loop  
    parameter signed [15:0] b0 = 16'h0400; // Coefficient for the feedforward loop  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            y_out <= 16'h0000;  
            y_prev <= 16'h0000;  
        end else begin  
            y_out <= (b0 * x_in + a1 * y_prev) >>> 10; // Shift to adjust for fixed point  
            y_prev <= y_out;  
        end  
    end  
endmodule

