module uart_transmitter (  
    input clk,  
    input reset,  
    input start,  
    input [7:0] data_in,  
    output reg tx,  
    output reg busy  
);  
    parameter IDLE = 2'b00, START_BIT = 2'b01, DATA_BITS = 2'b10, STOP_BIT = 2'b11;  
    parameter BAUD_RATE = 9600; // Example baud rate  

    reg [1:0] state;  
    reg [3:0] bit_count;  
    reg [15:0] baud_counter;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            tx <= 1; // Idle state for UART is high  
            busy <= 0;  
            bit_count <= 0;  
            baud_counter <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    busy <= 0;  
                    if (start) begin  
                        busy <= 1;  
                        state <= START_BIT;  
                        tx <= 0; // Start bit  
                    end  
                end  
                START_BIT: begin  
                    if (baud_counter == BAUD_RATE) begin  
                        baud_counter <= 0;  
                        state <= DATA_BITS;  
                        bit_count <= 0;  
                    end else begin  
                        baud_counter <= baud_counter + 1;  
                    end  
                end  
                DATA_BITS: begin  
                    if (baud_counter == BAUD_RATE) begin  
                        baud_counter <= 0;  
                        tx <= data_in[bit_count];  
                        bit_count <= bit_count + 1;  
                        if (bit_count == 7) begin  
                            state <= STOP_BIT;  
                        end  
                    end else begin  
                        baud_counter <= baud_counter + 1;  
                    end  
                end  
                STOP_BIT: begin  
                    if (baud_counter == BAUD_RATE) begin  
                        baud_counter <= 0;  
                        tx <= 1; // Stop bit  
                        state <= IDLE;  
                    end else begin  
                        baud_counter <= baud_counter + 1;  
                    end  
                end  
            endcase  
        end  
    end  
endmodule

