module butterworth_filter(  
    input clk,  
    input en,  
    input [15:0] x_in,  
    input [15:0] b_in,  
    output reg [15:0] y_out  
);  
    reg [15:0] x1, x2;  
    reg [15:0] y1, y2;  

    always @(posedge clk) begin  
        if (en) begin  
            // 2nd order Butterworth filter difference equation  
            y_out <= b_in * x_in + y1 + y2;  
            y2 <= y1;  
            y1 <= y_out;  
            x2 <= x1;  
            x1 <= x_in;  
        end  
    end  
endmodule

