module uart_tx #(parameter CLK_FREQ = 50000000, BAUD_RATE = 9600) (  
    input wire clk,  
    input wire rst,  
    input wire start,  
    input wire [7:0] data_in,  
    output reg tx,  
    output reg busy  
);  
    localparam CLOCKS_PER_BIT = CLK_FREQ / BAUD_RATE;  
    localparam STATE_IDLE = 2'b00, STATE_START = 2'b01, STATE_DATA = 2'b10, STATE_STOP = 2'b11;  

    reg [1:0] state, next_state;  
    reg [3:0] bit_count;  
    reg [12:0] clk_count;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= STATE_IDLE;  
            busy <= 1'b0;  
            tx <= 1'b1;  
        end else begin  
            state <= next_state;  
            if (state == STATE_DATA) begin  
                clk_count <= clk_count + 1;  
                if (clk_count == CLOCKS_PER_BIT - 1) begin  
                    clk_count <= 0;  
                    if (bit_count < 8) begin  
                        tx <= data_in[bit_count];  
                        bit_count <= bit_count + 1;  
                    end else begin  
                        next_state <= STATE_STOP;  
                    end  
                end  
            end  
        end  
    end  

    always @(*) begin  
        case (state)  
            STATE_IDLE: begin  
                if (start) begin  
                    busy = 1'b1;  
                    next_state = STATE_START;  
                    bit_count = 0;  
                    clk_count = 0;  
                    tx = 1'b0; // Start bit  
                end else begin  
                    next_state = STATE_IDLE;  
                end  
            end  
            STATE_START: begin  
                if (clk_count == CLOCKS_PER_BIT - 1) begin  
                    next_state = STATE_DATA;  
                end else begin  
                    next_state = STATE_START;  
                end  
            end  
            STATE_DATA: begin  
                if (bit_count == 8 && clk_count == CLOCKS_PER_BIT - 1) begin  
                    next_state = STATE_STOP;  
                end else begin  
                    next_state = STATE_DATA;  
                end  
            end  
            STATE_STOP: begin  
                if (clk_count == CLOCKS_PER_BIT - 1) begin  
                    busy = 1'b0;  
                    next_state = STATE_IDLE;  
                    tx = 1'b1; // Stop bit  
                end else begin  
                    next_state = STATE_STOP;  
                end  
            end  
            default: next_state = STATE_IDLE;  
        endcase  
    end  
endmodule

