module restoring_divider (  
    input clk,  
    input reset,  
    input [7:0] dividend,  
    input [3:0] divisor,  
    output reg [7:0] quotient,  
    output reg [7:0] remainder  
);  
    reg [7:0] temp_dividend;  
    reg [3:0] count;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            quotient <= 0;  
            remainder <= 0;  
            temp_dividend <= 0;  
            count <= 0;  
        end else begin  
            if (count < 8) begin  
                temp_dividend = (temp_dividend << 1) | dividend[7 - count];  
                quotient = quotient << 1;  
                if (temp_dividend >= divisor) begin  
                    temp_dividend = temp_dividend - divisor;  
                    quotient = quotient | 1;  
                end  
                count = count + 1;  
            end else begin  
                remainder = temp_dividend;  
                count = 0;  
                temp_dividend = 0;  
            end  
        end  
    end  
endmodule

