module uart_tx (
    input wire clk,
    input wire start,
    input wire [7:0] data,
    output reg tx,
    output reg tx_done
);
    reg [3:0] bit_index;
    reg [7:0] shift_reg;
    reg transmitting;

    always @(posedge clk) begin
        if (start && !transmitting) begin
            shift_reg <= data;
            bit_index <= 0;
            tx <= 0; // Start bit
            transmitting <= 1;
            tx_done <= 0;
        end else if (transmitting) begin
            if (bit_index < 8) begin
                tx <= shift_reg[bit_index]; // Transmit the next bit
                bit_index <= bit_index + 1;
            end else begin
                tx <= 1; // Stop bit
                transmitting <= 0;
                tx_done <= 1; // Indicate transmission completion
            end
        end
    end
endmodule

