    input wire reset,  
    input wire [7:0] fractional_value,  
    output reg clk_out  
);  
    reg [7:0] counter;  
    reg [7:0] divisor;  
    reg [15:0] phase_accumulator;  
    parameter INTEGER_DIVISOR = 128; // Example integer part of the divisor  

    always @(posedge clk_ref or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            phase_accumulator <= 0;  
            clk_out <= 0;  
        end else begin  
            counter <= counter + 1;  
            phase_accumulator <= phase_accumulator + fractional_value;  
            if (counter >= INTEGER_DIVISOR) begin  
                clk_out <= ~clk_out;  
                counter <= 0;  
            end  
        end  
    end  
endmodule

