module pcie_endpoint_controller (
    input wire clk,
    input wire rst_n,
    input wire start_read,
    input wire start_write,
    output reg [1:0] state // 2'b00: IDLE, 2'b01: READ, 2'b10: WRITE
);
    localparam IDLE = 2'b00;
    localparam READ = 2'b01;
    localparam WRITE = 2'b10;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            case (state)
                IDLE: begin
                    if (start_read) begin
                        state <= READ;
                    end else if (start_write) begin
                        state <= WRITE;
                    end
                end
                READ: begin
                    state <= IDLE;
                end
                WRITE: begin
                    state <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end
endmodule

