module rng_lfsr (
    input wire clk,
    input wire reset,
    input wire enable,
    input wire [7:0] seed,
    output reg [7:0] random_out
);
    reg [7:0] lfsr;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            lfsr <= seed;
            random_out <= 8'b0;
