module fractional_n_pll (  
    input wire clk_ref,  
    input wire reset,  
    input wire [7:0] numerator,  
    input wire [7:0] denominator,  
    output reg clk_out  
);  

    reg [15:0] count;  
    reg [15:0] target;  
    reg [7:0] divider;  

    always @(posedge clk_ref or posedge reset) begin  
        if (reset) begin  
            count <= 0;  
            clk_out <= 0;  
        end else begin  
            target <= numerator * (1 << 8) / denominator;  
            count <= count + 1;  
            if (count >= target) begin  
                count <= 0;  
                clk_out <= ~clk_out;  
            end  
        end  
    end  
endmodule

