module pwm_generator (  
    input wire clk,  
    input wire [3:0] duty_cycle,  
    output reg pwm_out  
);  
    reg [7:0] counter; // 8-bit counter to count clock cycles  
    always @(posedge clk) begin  
        if (counter < 8'hFF) begin  
            counter <= counter + 1;  
        end else begin  
            counter <= 0;  
        end  

        // Calculate the threshold for the PWM signal based on duty cycle  
        if (counter < (duty_cycle * 255) / 100) begin  
            pwm_out <= 1;  
        end else begin  
            pwm_out <= 0;  
        end  
    end  
endmodule

